const tenants = ["A","B","C"];
for (const t of tenants) {
  seedKafkaTopic(`tenant-${t}`, generateEvents(100));
  runSparkJob(`tenant-${t}`);
  verifyDashboard(`tenant-${t}`, expectedAggs);
}
```

